{
  "findings": [
    {
      "check_id": "CKV2_AWS_61",
      "title": "S3 bucket lacks a lifecycle configuration",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "The bucket has no lifecycle configuration to manage incomplete multipart uploads, which can leave abandoned data consuming storage indefinitely."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 bucket lacks a Public Access Block",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "No bucket-level Public Access Block is configured, so public ACLs or policies could expose flow-log data."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 access logging is not enabled",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "HIGH",
      "explanation": "The bucket does not record access requests, limiting detection and investigation of unauthorized access to flow logs."
    },
    {
      "check_id": "CKV_AWS_144",
      "title": "S3 cross-region replication is not enabled",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "MEDIUM",
      "explanation": "The flow-log bucket has no cross-region replication configuration, leaving its data dependent on a single AWS region."
    },
    {
      "check_id": "CKV_AWS_53",
      "title": "S3 bucket does not block public ACLs",
      "resource": "aws_s3_bucket.flowbucket",
      "severity": "CRITICAL",
      "explanation": "The bucket does not explicitly block public ACL creation, allowing a future ACL change to expose sensitive flow-log objects publicly."
    }
  ],
  "patched_code": "variable "flowlogs_access_log_bucket_name" {
  description = "Name of an existing, non-public S3 bucket in the same region that is configured to receive S3 server access logs."
  type        = string
}

variable "flowlogs_replication_destination_bucket_arn" {
  description = "ARN of an existing versioned S3 bucket in a different AWS region used as the replication destination."
  type        = string
}

resource "aws_s3_bucket" "flowbucket" {
  bucket        = "${local.resource_prefix.value}-flowlogs"
  force_destroy = true
  tags = merge({
    Name        = "${local.resource_prefix.value}-flowlogs"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_public_access_block" "flowbucket" {
  bucket = aws_s3_bucket.flowbucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_lifecycle_configuration" "flowbucket" {
  bucket = aws_s3_bucket.flowbucket.id

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

resource "aws_s3_bucket_logging" "flowbucket" {
  bucket        = aws_s3_bucket.flowbucket.id
  target_bucket = var.flowlogs_access_log_bucket_name
  target_prefix = "${aws_s3_bucket.flowbucket.id}/"
}

resource "aws_s3_bucket_versioning" "flowbucket" {
  bucket = aws_s3_bucket.flowbucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_role" "flowbucket_replication" {
  name = "${local.resource_prefix.value}-flowlogs-replication"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "flowbucket_replication" {
  name = "${local.resource_prefix.value}-flowlogs-replication"
  role = aws_iam_role.flowbucket_replication.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.flowbucket.arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionTagging"
        ]
        Resource = "${aws_s3_bucket.flowbucket.arn}/*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateDelete",
          "s3:ReplicateObject",
          "s3:ReplicateTags"
        ]
        Resource = "${var.flowlogs_replication_destination_bucket_arn}/*"
      }
    ]
  })
}

resource "aws_s3_bucket_replication_configuration" "flowbucket" {
  depends_on = [aws_s3_bucket_versioning.flowbucket]

  bucket = aws_s3_bucket.flowbucket.id
  role   = aws_iam_role.flowbucket_replication.arn

  rule {
    id       = "cross-region-replication"
    priority = 1
    status   = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    destination {
      bucket = var.flowlogs_replication_destination_bucket_arn
    }
  }
}
",
  "fix_summary": "Added comprehensive public-access blocking, a non-destructive lifecycle rule, server access logging, and versioning-backed cross-region replication. The replication role is restricted to the source and configured destination bucket; existing secure logging and replica buckets are supplied as inputs."
}
